import requests
from requests.auth import AuthBase
class RetryAuth(AuthBase):
    def __init__(self, token):
        self.token = token
    def __call__(self, r):
        r.headers['Authorization'] = f'Bearer {self.token}'
        r.register_hook('response', self.handle_401)
        return r
    def handle_401(self, response, **kwargs):
        if response.status_code == 401:
            self.token = 'refreshed_token'
            response.request.headers['Authorization'] = f'Bearer {self.token}'
            return response.connection.send(response.request)
        return response
s = requests.Session()
r = s.get('https://httpbin.org/bearer', auth=RetryAuth('expired_token'))
print(r.json().get('authenticated', False))

import requests
from requests.auth import AuthBase
class MultiStepAuth(AuthBase):
    def __call__(self, r):
        r.headers['X-Auth-Step'] = '1'
        r.register_hook('response', self.handle_response)
        return r
    def handle_response(self, response, **kwargs):
        if 'X-Next-Step' in response.headers:
            response.request.headers['X-Auth-Step'] = '2'
            return response.connection.send(response.request)
        return response
s = requests.Session()
r = s.get('https://httpbin.org/get', auth=MultiStepAuth())
print(r.request.headers.get('X-Auth-Step'))

