from requests.auth import AuthBase
class DigestAuth(AuthBase):
    def __init__(self, user, passwd):
        self.user = user
        self.passwd = passwd
    def __call__(self, r):
        r.headers['Authorization'] = 'Digest dummy'
        r.register_hook('response', self.handle_401)
        return r
    def handle_401(self, r, **kwargs):
        if r.status_code == 401:
            r.request.headers['Authorization'] = 'Digest real'
            r.request.headers['X-Retried'] = 'true'
            return r.connection.send(r.request)
        return r
s = requests.Session()
r = s.get('https://httpbin.org/digest-auth/auth/user/pass', auth=DigestAuth('user', 'pass'))
print(r.request.headers.get('X-Retried', 'false'))

import requests
from requests.adapters import HTTPAdapter
from urllib3.util.retry import Retry
class ConditionalRetryAdapter(HTTPAdapter):
    def send(self, request, **kwargs):
        if 'Retry-Count' in request.headers:
            kwargs['retries'] = Retry(total=5, backoff_factor=0.1)
        return super().send(request, **kwargs)
s = requests.Session()
s.mount('https://', ConditionalRetryAdapter())
r = s.get('https://httpbin.org/get', headers={'Retry-Count': 'true'})
print(r.status_code)

